.ds {
  --ds-bg:var(--p-bg,#e9edf2); --ds-surface:var(--p-surface,#f1f3f6); --ds-high:var(--p-high,#fafbfc);
  --ds-text:var(--p-ink,#2c333d); --ds-muted:var(--p-muted,#59636f);
  --ds-border:var(--p-line,#c2cad5); --ds-control-border:var(--p-control-border,#7b8592);
  --ds-soft:var(--p-soft,#d3e8de); --ds-accent:var(--p-accent,#303b48); --ds-on-accent:var(--p-on-accent,#ffffff);
  --ds-focus:var(--p-highlight,#6153b5); --ds-error:var(--p-error,#a3313e); --ds-success:var(--p-success,#26614f); --ds-warning:var(--p-warning,#805719);
  --ds-radius:var(--p-radius,24px); --ds-control-radius:var(--p-control-radius,16px);
  --ds-shadow:var(--p-shadow,6px 7px 16px #bbc4d166,-5px -5px 14px #ffffffed);
  --ds-raised:var(--p-raised,3px 4px 8px #b9c3d066,-3px -3px 8px #ffffffed);
  --ds-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55,inset -3px -3px 6px #ffffffd9);
  --ds-glass:var(--p-glass,#f6f8fbe8); --ds-disabled:var(--p-disabled,#dce1e8); --ds-duration:var(--p-duration,140ms);
  --ds-font:Pretendard,sans-serif; --ds-display-font:Outfit,Pretendard,sans-serif;
  --ds-text-sm:13px; --ds-text-md:16px; --ds-text-lg:24px;
  --ds-space-1:4px; --ds-space-2:8px; --ds-space-3:12px; --ds-space-4:16px; --ds-space-6:24px; --ds-space-8:32px;
  color:var(--ds-text); background:var(--ds-bg); font:var(--ds-text-md)/1.5 var(--ds-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-text-sm); margin-top:var(--ds-space-3); min-height:20px; color:var(--ds-muted); }
.ds .ds-surface { border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-shadow); border-color:#ffffff; }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-inset); background:var(--ds-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-high); box-shadow:0 8px 24px #38465e12; }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-field,.ds .ds-select-field { display:grid; gap:var(--ds-space-2); min-width:0; font-size:14px; }
.ds .ds-field > label,.ds .ds-select-field > span { font-weight:600; }
.ds .ds-help { font-size:var(--ds-text-sm); color:var(--ds-muted); line-height:1.5; }
.ds .ds-field[data-state="error"] .ds-help { color:var(--ds-error); }
.ds .ds-field[data-state="error"] .ds-help::before { content:'!'; display:inline-grid; place-items:center; width:14px; height:14px; font-size:11px; border:1px solid currentColor; border-radius:50%; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-help { color:var(--ds-success); }
.ds .ds-field[data-state="success"] .ds-help::before { content:'✓'; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-input { border-color:var(--ds-success); }
.ds .ds-field[data-state="focus"] .ds-input { outline:3px solid var(--ds-focus); outline-offset:3px; }

.ds .ds-input { display:block; width:100%; min-width:0; min-height:48px; padding:11px 14px; border:1px solid var(--ds-control-border); border-radius:var(--ds-control-radius); background:var(--ds-bg); box-shadow:var(--ds-inset); color:var(--ds-text); font-size:14px; line-height:1.5; }
.ds .ds-input::placeholder { color:var(--ds-muted); opacity:1; }
.ds .ds-input:disabled { opacity:1; box-shadow:none; color:var(--ds-muted); background:var(--ds-disabled); border-color:var(--ds-border); cursor:not-allowed; }
.ds .ds-input[aria-invalid="true"] { border-color:var(--ds-error); border-width:2px; padding:10px 13px; }
.ds label.ds-field { display:grid; gap:var(--ds-space-2); min-width:0; font-size:14px; }

.ds .ds-button { display:inline-flex; justify-content:center; align-items:center; gap:var(--ds-space-2); min-width:48px; min-height:48px; padding:10px 20px; border:1px solid var(--ds-accent); border-radius:var(--ds-control-radius); background:var(--ds-accent); color:var(--ds-on-accent); font-size:14px; font-weight:650; line-height:1.4; box-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24; text-decoration:none; transition:background var(--ds-duration),box-shadow var(--ds-duration); }
.ds .ds-button[data-variant="outline"] { border-color:var(--ds-control-border); color:var(--ds-text); background:var(--ds-surface); box-shadow:var(--ds-raised); }
.ds .ds-button[data-variant="ghost"] { color:var(--ds-text); background:transparent; border-color:transparent; box-shadow:none; }
.ds .ds-button[data-size="sm"] { min-height:44px; min-width:44px; padding:8px 16px; font-size:13px; }
.ds .ds-button[data-size="lg"] { min-height:56px; min-width:56px; padding:14px 24px; font-size:16px; }
.ds .ds-button[data-icon-only] { padding:10px; }
.ds .ds-button:not(:disabled):is(:hover,[data-state="hover"]) { background:color-mix(in srgb,var(--ds-accent) 84%,#000); }
.ds .ds-button[data-variant="outline"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--ds-high); }
.ds .ds-button[data-variant="ghost"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--ds-disabled); }
.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18; }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--ds-bg); box-shadow:var(--ds-inset); }
.ds .ds-button[data-state="focus"] { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ds-button:disabled { opacity:1; box-shadow:none; background:var(--ds-disabled); border-color:var(--ds-border); color:var(--ds-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--ds-accent); color:var(--ds-on-accent); border-color:var(--ds-accent); }
.ds .ds-spinner { width:16px; height:16px; flex-shrink:0; border:2px solid currentColor; border-right-color:transparent; border-radius:50%; animation:ds-spin .8s linear infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:dotted; } }

.ds .ds-card { display:flex; flex-direction:column; height:100%; background:var(--ds-surface); border:1px solid var(--ds-border); border-radius:var(--ds-radius); box-shadow:var(--ds-raised); overflow:hidden; }
.ds .ds-card[data-selected="true"] { border-color:var(--ds-success); background:#e7f0eb; }
.ds .ds-card-body { flex:1; padding:var(--ds-space-6); }
.ds .ds-card h3 { font-size:20px; line-height:1.45; font-weight:650; letter-spacing:-.035em; margin-top:var(--ds-space-4); }
.ds .ds-card p { font-size:14px; color:var(--ds-muted); margin-top:var(--ds-space-2); }
.ds .ds-card-actions { display:flex; justify-content:flex-end; padding:var(--ds-space-4) var(--ds-space-6); }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:4px 10px; border:1px solid var(--ds-border); border-radius:99px; background:var(--ds-soft); color:var(--ds-text); font-size:12px; line-height:1.5; font-weight:600; }
.ds .ds-badge[data-tone="success"] { background:#e5f2eb; border-color:#8fb8a5; color:var(--ds-success); }
.ds .ds-badge[data-tone="error"] { background:#f9e8e9; border-color:#d4a2a8; color:var(--ds-error); }
.ds .ds-badge[data-tone="warning"] { background:#f6efd9; border-color:#b9a16f; color:var(--ds-warning); }

.ds .ds-search-module { container-type:inline-size; }
.ds .ds-search-form { display:grid; grid-template-columns:minmax(0,1fr) minmax(90px,.3fr) auto; align-items:end; gap:var(--ds-space-3); }
.ds .ds-result-count { font-size:var(--ds-text-sm); color:var(--ds-muted); margin-block:var(--ds-space-6) var(--ds-space-4); }
.ds .ds-results { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr)); gap:var(--ds-space-6); }
.ds .ds-empty { padding:var(--ds-space-8); text-align:center; border:1px dashed var(--ds-control-border); border-radius:var(--ds-radius); }
.ds .ds-empty .ds-button { margin-top:var(--ds-space-4); }
.ds .ds-record-detail { padding:var(--ds-space-6); border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-record-detail h3 { font-size:var(--ds-text-lg); font-weight:650; }
.ds .ds-record-detail p { margin-top:var(--ds-space-3); color:var(--ds-muted); }
.ds .ds-record-detail > div { display:flex; flex-wrap:wrap; gap:var(--ds-space-3); margin-top:var(--ds-space-6); }
.ds .ds-record-detail [aria-pressed="true"] { background:var(--ds-success); border-color:var(--ds-success); }
@media(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
@container(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }

(function mountParts(root) {
  root.querySelectorAll('[data-indeterminate]').forEach(input => {
    if (!input.__pattoveInitialized) { input.indeterminate = true; input.__pattoveInitialized = true; }
  });
  if (root.__pattovePartsMounted) return;
  root.__pattovePartsMounted = true;
  function selectTab(tab) {
    const tabs = tab.closest('.ds-tabs');
    tabs.querySelectorAll('[role="tab"]').forEach(item => {
      const active = item === tab;
      item.setAttribute('aria-selected', String(active)); item.tabIndex = active ? 0 : -1;
      tabs.querySelector('#' + CSS.escape(item.getAttribute('aria-controls'))).hidden = !active;
    });
    tabs.dispatchEvent(new CustomEvent('pattove:tabchange', { bubbles: true, detail: { label: tab.textContent.trim(), panel: tab.getAttribute('aria-controls') } }));
  }
  function filter(form) {
    const module = form.closest('.ds-search-module');
    const query = form.elements.query.value.trim().toLocaleLowerCase();
    const status = form.elements.status.value;
    let count = 0;
    module.querySelectorAll('[data-result]').forEach(item => {
      const match = query.split(/\s+/).every(term => item.dataset.result.toLocaleLowerCase().includes(term)) && (status === 'all' || item.dataset.resultStatus === status);
      item.hidden = !match; if (match) count++;
    });
    module.querySelector('.ds-result-count').textContent = count + '개의 컬렉션';
    module.querySelector('.ds-empty').hidden = count > 0;
    module.querySelector('.ds-demo-note').textContent = '';
  }
  root.addEventListener('submit', event => {
    if (!event.target.matches('[data-part-search]')) return;
    event.preventDefault(); filter(event.target);
  });
  root.addEventListener('change', event => {
    if (event.target.matches('[data-part-search] select')) filter(event.target.form);
  });
  root.addEventListener('click', event => {
    const tab = event.target.closest('.ds-tab');
    if (tab) selectTab(tab);
    const button = event.target.closest('[data-part-action]');
    if (!button || button.disabled) return;
    const action = button.dataset.partAction;
    if (['open-record', 'close-record', 'save-record'].includes(action)) {
      const module = button.closest('.ds-search-module');
      const detail = module.querySelector('.ds-record-detail');
      if (action === 'save-record') {
        button.setAttribute('aria-pressed', String(button.getAttribute('aria-pressed') !== 'true'));
        module.__recordOpener.dataset.saved = button.getAttribute('aria-pressed');
        module.__recordOpener.setAttribute('aria-label', module.querySelector('.ds-record-detail h3').textContent + (button.getAttribute('aria-pressed') === 'true' ? ', 보관됨, 상세 열기' : ', 상세 열기'));
        module.querySelector('.ds-demo-note').textContent = button.getAttribute('aria-pressed') === 'true' ? '이 화면에서 컬렉션에 보관했어요.' : '보관을 해제했어요.';
        const record = module.__recordOpener.closest('[data-result]');
        module.dispatchEvent(new CustomEvent('pattove:save', { bubbles: true, detail: {
          id: record.dataset.recordId,
          title: detail.querySelector('h3').textContent,
          description: detail.querySelector('p').textContent,
          tag: record.dataset.resultStatus,
          saved: button.getAttribute('aria-pressed') === 'true'
        } }));
        return;
      }
      const open = action === 'open-record';
      if (open) {
        module.__recordOpener = button;
        const card = button.closest('.ds-card');
        detail.querySelector('h3').textContent = card.querySelector('h3').textContent;
        detail.querySelector('p').textContent = card.querySelector('.ds-card-body > p').textContent;
        detail.querySelector('[data-part-action="save-record"]').setAttribute('aria-pressed', button.dataset.saved || 'false');
      }
      module.querySelectorAll(':scope > form, :scope > .ds-result-count, :scope > .ds-results').forEach(element => { element.hidden = open; });
      detail.hidden = !open;
      module.querySelector('.ds-demo-note').textContent = '';
      if (open) detail.focus(); else module.__recordOpener?.focus();
    } else if (action === 'notify') {
      button.closest('.ds-feedback-example').querySelector('[data-part-feedback]').hidden = false;
    } else if (action === 'nav') {
      button.closest('nav').querySelectorAll('button').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      button.dispatchEvent(new CustomEvent('pattove:navigate', { bubbles: true, detail: { index: [...button.parentElement.children].indexOf(button), label: button.textContent.trim() } }));
    } else if (action === 'select-card') {
      const card = button.closest('.ds-card');
      const selected = card.dataset.selected !== 'true';
      card.dataset.selected = String(selected);
      button.setAttribute('aria-pressed', String(selected));
      button.lastChild.textContent = selected ? '선택됨' : '선택하기';
      card.dispatchEvent(new CustomEvent('pattove:select', { bubbles: true, detail: { selected, title: card.querySelector('h3').textContent } }));
    } else if (action === 'reset-search') {
      const form = button.closest('.ds-search-module').querySelector('form');
      form.reset(); filter(form); form.elements.query.focus();
    } else if (action === 'press') {
      button.dispatchEvent(new CustomEvent('pattove:action', { bubbles: true, detail: { label: button.getAttribute('aria-label') || button.textContent.trim() } }));
      const region = button.closest('.ds-search-module, .part-demo, .specimen') || root;
      const output = region.querySelector('.ds-demo-note');
      if (output) {
        const card = button.closest('.ds-card');
        output.textContent = card ? card.querySelector('h3').textContent + ' 선택됨' : (button.getAttribute('aria-label') || button.textContent.trim()) + ' 버튼을 눌렀어요.';
      }
    }
  });
  root.addEventListener('keydown', event => {
    const tab = event.target.closest('.ds-tab');
    if (!tab || !['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const tabs = [...tab.closest('[role="tablist"]').querySelectorAll('.ds-tab')];
    const current = tabs.indexOf(tab);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
    selectTab(tabs[next]); tabs[next].focus();
  });
})(document);

